import json, sys, base64, re, html

def dec(data):
    if not data:
        return ""
    data = data.replace('-', '+').replace('_', '/')
    data += '=' * (-len(data) % 4)
    try:
        return base64.b64decode(data).decode('utf-8', errors='replace')
    except Exception:
        return ""

def walk(p, plain, htm):
    mt = (p.get('mimeType') or '').lower()
    body = p.get('body') or {}
    d = body.get('data')
    if d and not (p.get('filename')):
        t = dec(d)
        if mt.startswith('text/html'):
            htm.append(t)
        else:
            plain.append(t)
    for c in p.get('parts') or []:
        walk(c, plain, htm)

def strip(h):
    h = re.sub(r'(?is)<(script|style)[^>]*>.*?</\1>', ' ', h)
    h = re.sub(r'(?i)<br\s*/?>|</p>|</div>|</tr>', '\n', h)
    h = re.sub(r'<[^>]+>', ' ', h)
    h = html.unescape(h)
    h = re.sub(r'[ \t\r\f\v]+', ' ', h)
    h = re.sub(r'\n\s*\n+', '\n\n', h)
    return h.strip()

def load(path):
    raw = open(path).read()
    obj = json.loads(raw)
    # tool results may be wrapped as list of content blocks
    if isinstance(obj, list) and obj and isinstance(obj[0], dict) and 'text' in obj[0]:
        obj = json.loads(obj[0]['text'])
    if isinstance(obj, dict) and 'messages' not in obj and 'result' in obj:
        obj = obj['result']
        if isinstance(obj, str):
            obj = json.loads(obj)
    return obj

obj = load(sys.argv[1])
out = open('/tmp/mail_part1.jsonl', 'a')
n = 0
for m in obj.get('messages', []):
    p = m.get('payload') or {}
    hdrs = {}
    for h in p.get('headers') or []:
        hdrs.setdefault(h['name'].lower(), h['value'])
    plain, htm = [], []
    walk(p, plain, htm)
    text = "\n".join(t for t in plain if t.strip())
    if not text.strip():
        text = "\n".join(strip(h) for h in htm)
    rec = {"id": m.get('id'), "internalDate": m.get('internalDate'),
           "Date": hdrs.get('date'), "From": hdrs.get('from'),
           "Subject": hdrs.get('subject'), "body": text}
    out.write(json.dumps(rec, ensure_ascii=False) + "\n")
    n += 1
print("wrote", n, "not_found:", obj.get('not_found'))

